/**
 * toast-error — unit tests for safe error serialisation.
 *
 * Guards the P0 regression: toast must never display "[object Object]".
 * The pattern under test is the guard used in CampaignConfirmDialog.handleConfirm()
 * and any other marketing toast call site:
 *
 *   const message = err instanceof Error ? err.message : String(err)
 *   toast.error(message || 'Failed to send campaign')
 *
 * This file tests that helper in isolation.
 */

import { describe, it, expect } from 'vitest'

// ── Helper under test (inline — mirrors the exact guard in CampaignConfirmDialog) ──

function safeErrorMessage(err: unknown, fallback = 'An error occurred'): string {
  const message = err instanceof Error ? err.message : String(err)
  return message || fallback
}

// ── Tests ──────────────────────────────────────────────────────────────────────

describe('safeErrorMessage — toast error serialisation', () => {
  it('returns the message from an Error object', () => {
    const err = new Error('Deposit failed')
    expect(safeErrorMessage(err)).toBe('Deposit failed')
  })

  it('returns the string itself when passed a plain string', () => {
    expect(safeErrorMessage('Failed to send campaign')).toBe('Failed to send campaign')
  })

  it('never returns "[object Object]" for a plain object', () => {
    const err: unknown = { code: 'ECONNRESET', reason: 'timeout' }
    const result = safeErrorMessage(err)
    expect(result).not.toBe('[object Object]')
    expect(result).not.toContain('[object Object]')
  })

  it('returns fallback for undefined', () => {
    const result = safeErrorMessage(undefined)
    // String(undefined) === "undefined" — still not "[object Object]"
    expect(result).not.toContain('[object Object]')
    expect(typeof result).toBe('string')
  })

  it('returns fallback for null', () => {
    const result = safeErrorMessage(null)
    expect(result).not.toContain('[object Object]')
    expect(typeof result).toBe('string')
  })

  it('returns fallback when message is empty string', () => {
    const err = new Error('')
    const result = safeErrorMessage(err, 'Failed to send campaign')
    expect(result).toBe('Failed to send campaign')
  })

  it('preserves the message from subclasses of Error', () => {
    class ApiError extends Error {
      constructor(msg: string, public status: number) { super(msg) }
    }
    const err = new ApiError('Rate limit exceeded', 429)
    expect(safeErrorMessage(err)).toBe('Rate limit exceeded')
  })

  it('handles a number thrown as an error value', () => {
    const result = safeErrorMessage(42)
    expect(result).toBe('42')
    expect(result).not.toContain('[object Object]')
  })

  it('handles an array thrown as an error value', () => {
    const result = safeErrorMessage(['err1', 'err2'])
    expect(result).not.toBe('[object Object]')
    expect(typeof result).toBe('string')
  })
})

/**
 * audience-filter — unit tests for AudienceFilterBuilder serialisation logic.
 *
 * Tests the pure functions extracted from AudienceFilterBuilder.tsx:
 *   buildLegacyFilter(groups)  — Group[] → AudienceFilter (flat, RPC-compatible)
 *   initGroups(value)          — AudienceFilter → Group[] (initialise builder state)
 *
 * These functions have no React / DOM dependency — tested in plain TS.
 */

import { describe, it, expect } from 'vitest'
import type { AudienceFilter } from '@/lib/marketing/types'

// ── Re-implement the pure helpers here rather than importing from the component
// to avoid pulling in the React/DOM surface and all its peer deps.
// If the component is ever refactored to export these, swap the import.

type ConditionType = 'tags' | 'last_visit_days' | 'min_spent_cents' | 'max_spent_cents' | 'location_ids'
type GroupOp = 'AND' | 'OR'

interface Condition {
  id: string
  type: ConditionType
  value: string
}

interface Group {
  id: string
  op: GroupOp
  conditions: Condition[]
}

let _seq = 0
function idGen() { return `id-${++_seq}` }

function buildLegacyFilter(groups: Group[]): AudienceFilter {
  const first = groups[0]
  if (!first) return {}
  const filter: AudienceFilter = {}
  const tags: string[] = []
  const locationIds: string[] = []
  for (const c of first.conditions) {
    if (!c.value) continue
    switch (c.type) {
      case 'tags':
        tags.push(c.value)
        break
      case 'last_visit_days': {
        const v = parseInt(c.value, 10)
        if (v) filter.last_visit_days = v
        break
      }
      case 'min_spent_cents': {
        const v = Math.round(parseFloat(c.value) * 100)
        if (v) filter.min_spent_cents = v
        break
      }
      case 'max_spent_cents': {
        const v = Math.round(parseFloat(c.value) * 100)
        if (v) filter.max_spent_cents = v
        break
      }
      case 'location_ids':
        locationIds.push(c.value)
        break
    }
  }
  if (tags.length) filter.tags = tags
  if (locationIds.length) filter.location_ids = locationIds
  return filter
}

function initGroups(value: AudienceFilter): Group[] {
  const conditions: Condition[] = []
  if (value.tags) {
    for (const t of value.tags) conditions.push({ id: idGen(), type: 'tags', value: t })
  }
  if (value.last_visit_days !== undefined) {
    conditions.push({ id: idGen(), type: 'last_visit_days', value: String(value.last_visit_days) })
  }
  if (value.min_spent_cents !== undefined) {
    conditions.push({ id: idGen(), type: 'min_spent_cents', value: String(value.min_spent_cents / 100) })
  }
  if (value.max_spent_cents !== undefined) {
    conditions.push({ id: idGen(), type: 'max_spent_cents', value: String(value.max_spent_cents / 100) })
  }
  if (value.location_ids) {
    for (const id of value.location_ids) conditions.push({ id: idGen(), type: 'location_ids', value: id })
  }
  return [{ id: idGen(), op: 'AND', conditions }]
}

