type QueryResult<T> = { data: T | null; error: null }
type ChainBuilder<T> = {
  select: (_cols: string) => ChainBuilder<T>
  eq: (_col: string, _val: unknown) => ChainBuilder<T>
  maybeSingle: () => Promise<QueryResult<T>>
  single: () => Promise<QueryResult<T>>
  order: (_col: string, _opts?: unknown) => ChainBuilder<T>
  limit: (_n: number) => ChainBuilder<T>
  update: (_data: unknown) => ChainBuilder<T>
}

function chain<T>(data: T | null): ChainBuilder<T> {
  const self: ChainBuilder<T> = {
    select: () => self,
    eq: () => self,
    order: () => self,
    limit: () => self,
    update: () => self,
    maybeSingle: () => Promise.resolve({ data, error: null }),
    single: () => Promise.resolve({ data, error: null }),
  }
  return self
}

